options.helpers:
/* ⚠ 원래 레코딩 룰(queue:info)에 있던 값. 출처가 되는 메트릭이 없어서
   (엑셀 배분표에만 있음) 룰을 안 쓰면 여기에 옮겨 적어야 한다.
   대시보드가 늘어나면 이 블록도 그만큼 복제된다. */
const INFO = {
  "root.platform": {service:"PLATFORM", service_ko:"플랫폼 운영 관리", team:"AI/Data Platform",
    ldap:"platform", ns_app:"app-platform", ns_sql:"sql-platform", sql_engine:"O",
    catalog:"all", bucket:"ic-platform"},
  "root.fdc": {service:"FDC", service_ko:"FDC 서비스", team:"AI/Data Platform",
    ldap:"fdc", ns_app:"app-fdc", ns_sql:"-", sql_engine:"X",
    catalog:"-", bucket:"fdc, ic-lfdc, ic-m…"},
  "root.smartbig": {service:"SMARTBIG", service_ko:"Smart Big 서비스", team:"품질 지능화",
    ldap:"smartbig", ns_app:"app-smartbig", ns_sql:"sql-smartbig", sql_engine:"O",
    catalog:"icberg, icnfa, smartbig, tas, pntchp", bucket:"ic-smartbig, ic-ees, ic-bmc, ic-wt …"},
  "root.yms": {service:"YMS", service_ko:"Smart YMS 서비스", team:"품질 지능화",
    ldap:"yms", ns_app:"app-yms", ns_sql:"-", sql_engine:"O",
    catalog:"(팀 공통)", bucket:"(팀 공통)"},
  "root.tttm": {service:"TTTM", service_ko:"-", team:"EES/MDM/IPA",
    ldap:"tttm", ns_app:"app-tttm", ns_sql:"sql-tttm", sql_engine:"O",
    catalog:"icberg", bucket:"ic-tttm"},
  "root.pluto": {service:"PLUTO", service_ko:"-", team:"장비 지능화",
    ldap:"pluto", ns_app:"app-pluto", ns_sql:"sql-pluto", sql_engine:"O",
    catalog:"icberg", bucket:"ic-pluto"},
};

/* queue:plan_* 4종. 병합셀(fdc·yms 의 trino/pods)은 null 이어야 한다. */
const PLAN = {
  "root.platform": {spark:0,    trino:30,   pods:6,    guar:230},
  "root.fdc":      {spark:2900, trino:null, pods:null, guar:2900},
  "root.smartbig": {spark:1000, trino:2350, pods:80,   guar:3350},
  "root.yms":      {spark:1400, trino:null, pods:null, guar:1400},
  "root.tttm":     {spark:100,  trino:590,  pods:20,   guar:690},
  "root.pluto":    {spark:1100, trino:1170, pods:40,   guar:2270},
};

/* Business Text v6 실행 규약 (소스 실측):
     - 이 코드는 new Function('context', code) 로 실행된다 → 변수명은 context.
     - **반환값은 렌더에 쓰이지 않는다.** 실제 렌더는 content(Handlebars) 가 한다.
       → 여기서는 handlebars helper 를 등록하고, content 에서 {{{matrix}}} 로 부른다.
     - renderMode='data' 일 때 panelData.series 에 전 refId 프레임이 들어온다.
     - 최종 HTML 은 DOMPurify(USE_PROFILES:{html:true}) 를 통과한다
       → table/td/colspan/class/style 은 살아남고 script/on* 은 제거된다. */
const H = context.handlebars;
const COLORS = {"AI/Data Platform":"#2a78d6","품질 지능화":"#eb6834",
                "EES/MDM/IPA":"#1baf7a","장비 지능화":"#eda100"};
const ORDER = ["root.platform","root.fdc","root.smartbig","root.yms","root.tttm","root.pluto"];

/* refId 별 프레임을 큐 기준 레코드로 정규화.

   ⚠ 프레임 형태가 두 가지일 수 있다 (실측 근거):
     (a) time_series 형태 — refId 당 시리즈마다 프레임 1개, **라벨이 값 필드에** 붙는다.
         /api/ds/query(백엔드 직접 호출)로 확인한 실제 모양이 이것이다.
     (b) table 형태 — 라벨이 컬럼으로 펼쳐진 프레임 1개.
         format:"table" 은 Prometheus **프론트엔드** 데이터소스가 적용하므로
         패널 안에서는 이쪽이 올 수 있다.
   어느 쪽이 올지 렌더 없이 확정할 수 없어 **둘 다 처리**한다. */
function arr(f){ return (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []); }

function collect(series, refId){
  const out = {};
  series.filter(s => s.refId === refId).forEach(f => {
    const names = (f.fields || []).map(x => x.name);
    const qi = names.indexOf("queue");

    if (qi >= 0) {                                   /* (b) table 형태 */
      const cols = {};
      names.forEach((n,i) => { cols[n] = arr(f.fields[i]); });
      let vn = names.find(n => n === "Value" || n.indexOf("Value") === 0);
      if (!vn) vn = names.find(n => n !== "Time" && f.fields[names.indexOf(n)].type === "number");
      (cols["queue"] || []).forEach((q, r) => {
        const rec = out[q] || (out[q] = {});
        names.forEach(n => { if (n !== "Time") rec[n] = cols[n][r]; });
        if (vn) rec.__v = cols[vn][r];
      });
      return;
    }

    /* (a) time_series 형태 — 라벨이 값 필드에 */
    const vf = (f.fields || []).find(x => x.type === "number")
            || (f.fields || [])[(f.fields || []).length - 1];
    const lab = (vf && vf.labels) || {};
    if (!lab.queue) return;
    const rec = out[lab.queue] || (out[lab.queue] = {});
    Object.keys(lab).forEach(k => { rec[k] = lab[k]; });
    const vs = arr(vf);
    rec.__v = vs.length ? vs[vs.length - 1] : null;
  });
  return out;
}
const val = (m) => { const o = {}; Object.keys(m).forEach(q => { o[q] = m[q].__v; }); return o; };

const S = (context.panelData && context.panelData.series) || [];
const meta = INFO;
/* collect() 는 queue 라벨도 레코드에 넣어줬다 — 하드코딩 표엔 없으니 키에서 채운다 */
Object.keys(meta).forEach(q => { meta[q].queue = q; });
const spark = {}, trino = {}, planpods = {}, guar = {};
Object.keys(PLAN).forEach(q => { spark[q] = PLAN[q].spark; trino[q] = PLAN[q].trino;
                                 planpods[q] = PLAN[q].pods; guar[q] = PLAN[q].guar; });
const lq = val(collect(S,"labquota")), lu = val(collect(S,"labused"));
const mq = val(collect(S,"memquota")), mu = val(collect(S,"memused"));
const pods = val(collect(S,"pods")), ovf = val(collect(S,"overflow"));

const queues = ORDER.filter(q => meta[q]);
if (!queues.length) {
  H.registerHelper('matrix', () => new H.SafeString(
    '<div style="padding:16px;opacity:.7">데이터 없음 — info 프레임에서 queue 를 찾지 못했습니다.<br>'
    + 'frames=' + S.length + ' · refIds=' + S.map(s=>s.refId).join(",") + '<br>'
    + 'info fields=' + JSON.stringify((S.filter(s=>s.refId==="info")[0]||{fields:[]}).fields.map(f=>f.name))
    + '</div>'));
  return;
}

/* 팀 밴드: 연속된 같은 팀을 colspan 으로 묶는다 (이미지의 상단 색 띠) */
const bands = [];
queues.forEach(q => {
  const t = meta[q].team;
  if (bands.length && bands[bands.length-1].team === t) bands[bands.length-1].span++;
  else bands.push({team:t, span:1});
});

const fmt = (v,d)=> v==null||isNaN(v) ? "—" : Number(v).toLocaleString("ko-KR",{minimumFractionDigits:d||0,maximumFractionDigits:d||0});
const pct = (a,b)=> (b && !isNaN(a)) ? a/b*100 : null;
function stat(p){ if(p==null) return ["","—"];
  if(p>=100) return ["crit","초과"]; if(p>=90) return ["ser","임박"];
  if(p>=75) return ["warn","주의"]; return ["ok","여유"]; }

/* 값 + % + 진행막대를 한 셀에 (이미지의 CPU/Memory/S3 사용 행) */
function useCell(used, quota, dec, unit){
  const p = pct(used, quota);
  if (used == null) return '<td class="mx-c mx-dim">—</td>';
  const [cls] = stat(p);
  const w = Math.min(100, p==null?0:p);
  const ovr = p!=null && p>100 ? Math.min(100, p-100) : 0;
  return '<td class="mx-c">'
    + '<div class="mx-uv"><span class="mx-n">'+fmt(used,dec)+'</span>'
    + '<span class="mx-p">'+(p==null?"—":p.toFixed(0)+"%")+'</span></div>'
    + '<div class="mx-bar"><i class="'+cls+'" style="width:'+w+'%"></i>'
    + (ovr? '<b style="width:'+ovr+'%"></b>':'') + '</div></td>';
}

const totGuar = queues.reduce((a,q)=> a + (guar[q]||0), 0);
let h = '';

/* ── 헤더: 팀 밴드 + 서비스 ── */
h += '<table class="mx"><thead>';
h += '<tr><th class="mx-h mx-lab">팀</th>';
bands.forEach(b => { h += '<th class="mx-team" colspan="'+b.span+'" style="background:'+(COLORS[b.team]||"#8a93a3")+'">'+b.team+'</th>'; });
h += '</tr><tr><th class="mx-h mx-lab">서비스</th>';
queues.forEach(q => { const m=meta[q];
  h += '<th class="mx-svc" style="border-bottom:3px solid '+(COLORS[m.team]||"#8a93a3")+'">'
     + '<div class="mx-svc-id">'+m.service+'</div>'
     + (m.service_ko && m.service_ko!=="-" ? '<div class="mx-svc-ko">'+m.service_ko+'</div>' : '')
     + '</th>'; });
h += '</tr></thead><tbody>';

/* ── 구성 정보 행 ── */
const rowTag = (label, key) => {
  let r = '<tr><td class="mx-lab">'+label+'</td>';
  queues.forEach(q => { r += '<td class="mx-c"><code class="mx-tag">'+(meta[q][key]||"—")+'</code></td>'; });
  return r + '</tr>';
};
h += rowTag("LDAP","ldap");
h += rowTag("Schedule Queue","queue");
h += '<tr><td class="mx-lab">SQL Engine</td>';
queues.forEach(q => { const v=meta[q].sql_engine;
  h += '<td class="mx-c"><b class="'+(v==="O"?"mx-o":"mx-x")+'">'+v+'</b></td>'; });
h += '</tr>';
['Trino Catalog:catalog','Bucket 구성:bucket'].forEach(spec => {
  const [lbl,key]=spec.split(":");
  h += '<tr><td class="mx-lab">'+lbl+'</td>';
  queues.forEach(q => { h += '<td class="mx-c mx-txt">'+(meta[q][key]||"—")+'</td>'; });
  h += '</tr>';
});

/* ── 배분 계획값 (섹션 머리 + 병합 셀) ── */
h += '<tr class="mx-sec"><td class="mx-lab">APACHE SPARK vCores</td>';
queues.forEach(q => { h += '<td class="mx-c mx-num">'+fmt(spark[q])+'</td>'; });
h += '</tr>';

/* Trino·Pod 은 SMARTBIG+YMS 가 원본 표에서 병합 셀 → colspan 으로 재현 */
function mergedRow(label, map, note){
  let r = '<tr><td class="mx-lab">'+label+'</td>';
  for (let i=0;i<queues.length;i++){
    const q=queues[i];
    if (q==="root.smartbig" && queues[i+1]==="root.yms"){
      r += '<td class="mx-c mx-num mx-merge" colspan="2">'+fmt(map[q])
         + '<div class="mx-note">'+note+'</div></td>'; i++;
    } else r += '<td class="mx-c mx-num">'+(map[q]==null?"—":fmt(map[q]))+'</td>';
  }
  return r+'</tr>';
}
h += mergedRow("Trino vCores", trino, "SMARTBIG + YMS 공통");
h += mergedRow("Pod 수", planpods, "SMARTBIG + YMS 공통");

h += '<tr class="mx-sec"><td class="mx-lab">보장자원 GUARANTEED</td>';
queues.forEach(q => { h += '<td class="mx-c mx-num">'+fmt(guar[q])+'</td>'; });
h += '</tr>';

/* ── 실측 사용 행 (값 + % + 막대) ── */
h += '<tr><td class="mx-lab">CPU 사용 <span class="mx-u">cores</span></td>';
queues.forEach(q => { h += useCell(lu[q], lq[q], 2); });
h += '</tr>';
h += '<tr><td class="mx-lab">Memory 사용 <span class="mx-u">GiB</span></td>';
queues.forEach(q => { const u=mu[q]!=null?mu[q]/1073741824:null, k=mq[q]!=null?mq[q]/1073741824:null;
  h += useCell(u, k, 1); });
h += '</tr>';
h += '<tr><td class="mx-lab">공용 차용 <span class="mx-u">cores</span></td>';
queues.forEach(q => { const v=ovf[q];
  h += '<td class="mx-c mx-num'+(v>0?" mx-ovf":"")+'">'+(v==null?"—":fmt(v,2))+'</td>'; });
h += '</tr>';
h += '<tr><td class="mx-lab">실행 파드</td>';
queues.forEach(q => { h += '<td class="mx-c mx-num">'+(pods[q]==null?"—":fmt(pods[q]))+'</td>'; });
h += '</tr>';

/* ── 상태 · 비중 ── */
h += '<tr><td class="mx-lab">상태</td>';
queues.forEach(q => { const p=pct(lu[q],lq[q]); const [cls,lbl]=stat(p);
  h += '<td class="mx-c">'+(p==null?'<span class="mx-dim">—</span>'
     : '<span class="mx-pill '+cls+'">'+lbl+' '+p.toFixed(0)+'%</span>')+'</td>'; });
h += '</tr>';
h += '<tr class="mx-sec"><td class="mx-lab">전체 비중 <span class="mx-u">보장 기준</span></td>';
queues.forEach(q => { h += '<td class="mx-c mx-num">'+(totGuar?((guar[q]/totGuar*100).toFixed(1)+"%"):"—")+'</td>'; });
h += '</tr>';

h += '</tbody></table>';
h += '<div class="mx-legend">'
  +  '<span><i class="sw ok"></i>보장 범위 내 사용</span>'
  +  '<span><i class="sw hatch"></i>공용자원에서 끌어쓴 몫</span>'
  +  '<span class="mx-dim">회색 배경 = 원본 표에서 셀 병합(팀 공통)</span>'
  +  '</div>';

MATRIX_HTML = h;
H.registerHelper('matrix', () => new H.SafeString(MATRIX_HTML));

options.styles:
.mx{border-collapse:separate;border-spacing:0;width:100%;font-size:12.5px;
    font-family:system-ui,-apple-system,"Segoe UI","Noto Sans KR","Malgun Gothic",sans-serif}
.mx th,.mx td{padding:6px 9px;text-align:center;vertical-align:middle;
    border-right:1px solid rgba(128,138,155,.18);border-bottom:1px solid rgba(128,138,155,.18)}
.mx .mx-lab{text-align:left;white-space:nowrap;font-weight:600;
    border-right:1px solid rgba(128,138,155,.45);min-width:150px}
.mx .mx-u{font-weight:400;opacity:.6;font-size:11px}
.mx .mx-team{color:#fff;font-weight:700;font-size:12.5px;letter-spacing:-.01em;
    border-radius:4px 4px 0 0;border-right:2px solid var(--panel-bg,transparent)}
.mx .mx-svc{padding:7px 9px}
.mx .mx-svc-id{font-family:ui-monospace,Menlo,Consolas,monospace;font-weight:700;font-size:12.5px}
.mx .mx-svc-ko{font-size:10.5px;opacity:.65;margin-top:2px}
.mx tr.mx-sec td{background:rgba(128,138,155,.10);font-weight:650}
.mx tr.mx-sec .mx-lab{text-transform:uppercase;letter-spacing:.06em;font-size:11px;opacity:.85}
.mx .mx-num{font-family:ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}
.mx .mx-txt{font-size:11px;opacity:.85;max-width:210px;white-space:normal;line-height:1.45}
.mx .mx-tag{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:11px;
    padding:1px 6px;border:1px solid rgba(128,138,155,.45);border-radius:3px}
.mx .mx-o{color:#0ca30c;font-family:ui-monospace,monospace;font-weight:700}
.mx .mx-x{color:#d03b3b;font-family:ui-monospace,monospace;font-weight:700}
.mx .mx-merge{background:rgba(128,138,155,.10)}
.mx .mx-note{font-size:10px;opacity:.6;margin-top:2px;font-family:inherit}
.mx .mx-dim{opacity:.45}
.mx .mx-ovf{color:#ec835a;font-weight:650}
.mx .mx-uv{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.mx .mx-n{font-family:ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}
.mx .mx-p{font-family:ui-monospace,monospace;font-size:11px;opacity:.7}
.mx .mx-bar{height:6px;border-radius:3px;background:rgba(128,138,155,.22);
    overflow:hidden;margin-top:4px;display:flex}
.mx .mx-bar i{display:block;height:100%;border-radius:3px}
.mx .mx-bar i.ok{background:#2a78d6} .mx .mx-bar i.warn{background:#fab219}
.mx .mx-bar i.ser{background:#ec835a} .mx .mx-bar i.crit{background:#d03b3b}
.mx .mx-bar b{display:block;height:100%;
    background:repeating-linear-gradient(45deg,rgba(255,255,255,.65) 0 2px,transparent 2px 5px),#d03b3b}
.mx-pill{display:inline-block;font-size:11px;font-weight:650;padding:1.5px 7px;border-radius:3px;
    font-family:ui-monospace,monospace}
.mx-pill.ok{color:#0ca30c;background:rgba(12,163,12,.14)}
.mx-pill.warn{color:#fab219;background:rgba(250,178,25,.18)}
.mx-pill.ser{color:#ec835a;background:rgba(236,131,90,.18)}
.mx-pill.crit{color:#d03b3b;background:rgba(208,59,59,.15)}
.mx-legend{display:flex;gap:16px;flex-wrap:wrap;font-size:11.5px;opacity:.8;margin-top:10px}
.mx-legend .sw{width:10px;height:10px;border-radius:2px;display:inline-block;margin-right:5px}
.mx-legend .sw.ok{background:#2a78d6}
.mx-legend .sw.hatch{background:repeating-linear-gradient(45deg,#d03b3b 0 2px,transparent 2px 5px),rgba(128,138,155,.3)}

targets.expr:
sum by (cluster,queue) (
  kube_pod_container_resource_requests{cluster="$cluster", resource="cpu"}
  * on (namespace,pod) group_left(queue)
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
)

sum by (cluster,queue) (
  kube_pod_container_resource_requests{cluster="$cluster", resource="memory"}
  * on (namespace,pod) group_left(queue)
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
)

count by (cluster,queue) (
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
)

clamp_min(
  (sum by (cluster,queue) (
  kube_pod_container_resource_requests{cluster="$cluster", resource="cpu"}
  * on (namespace,pod) group_left(queue)
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
))
  - on (cluster,queue) group_left()
  (max by (cluster,queue) (
label_replace(
  {__name__=~"yunikorn_[a-z0-9]+_queue_resource",
   __name__!="yunikorn_root_queue_resource",
   cluster="$cluster", resource="vcore", state="guaranteed"},
  "queue", "root.$1", "__name__", "yunikorn_(.+)_queue_resource"
) / 1000
)),
  0
)

sum(sum by (cluster,queue) (
  kube_pod_container_resource_requests{cluster="$cluster", resource="cpu"}
  * on (namespace,pod) group_left(queue)
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
))

sum(sum by (cluster,queue) (
  kube_pod_container_resource_requests{cluster="$cluster", resource="memory"}
  * on (namespace,pod) group_left(queue)
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
))

sum(clamp_min(
  (sum by (cluster,queue) (
  kube_pod_container_resource_requests{cluster="$cluster", resource="cpu"}
  * on (namespace,pod) group_left(queue)
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
))
  - on (cluster,queue) group_left()
  (max by (cluster,queue) (
label_replace(
  {__name__=~"yunikorn_[a-z0-9]+_queue_resource",
   __name__!="yunikorn_root_queue_resource",
   cluster="$cluster", resource="vcore", state="guaranteed"},
  "queue", "root.$1", "__name__", "yunikorn_(.+)_queue_resource"
) / 1000
)),
  0
))

sum(sum by (cluster,queue) (
  kube_pod_container_resource_requests{cluster="$cluster", resource="cpu"}
  * on (namespace,pod) group_left(queue)
  label_replace(
    kube_pod_annotations{cluster="$cluster", annotation_yunikorn_apache_org_queue!=""},
    "queue", "$1", "annotation_yunikorn_apache_org_queue", "(.+)"
  )
